def card(work):
    pre = {'1000 subscribers': 'weekly videos for 8 weeks', 'weekly videos for 8 weeks': 'template + 4 scripts', 'template + 4 scripts': 'channel set up', 'channel set up': 'today'}
    plan = backcast_plan('1000 subscribers', pre, 'today')
    save(work, 'backcast.json', plan)
    broken = False
    try:
        backcast_plan('1000 subscribers', {'1000 subscribers': 'luck'}, 'today')
