        broken = True
    return [eq('first step is today', plan[0]['milestone'], 'today'), eq('last is end state', plan[-1]['milestone'], '1000 subscribers'), truth('every milestone has a done-test', all((p['done_test'] for p in plan))), truth('gap in chain rejected', broken)]

